@app.route('/')
def index():
    if 'user' in session:
        # User already authenticated – redirect to noVNC URL
        return redirect(url_for('novnc', cb=int(time.time())))
    
    error = request.args.get('error')
    if error:
        return render_template_string(LOGIN_PAGE, error=error)
    return redirect(url_for('saml_login'))

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('index'))

